-- with the Signature reference content. Does nothing once the content was edited or published.
UPDATE "revisions" SET "content" = $seed${"contentVersion":1,"name":"Tandjung Sari","tagline":"A private retreat in Bali","heroTitle":"Our Story","intro":"Beyond the rush, beneath the palms. A small collection of private villas made for slow mornings, unhurried conversations, and the simple pleasure of feeling at home.","storyTitle":"Rooted in Bali. Made for you.","story":"Sodai began with a simple idea: make room for the things that matter. The sound of water. A meal shared slowly. A garden that changes with the light.\n\nOur fictional villa collection celebrates the island’s natural rhythm through open spaces, honest materials, and thoughtful hospitality. This is an illustrative website demo, rather than a real property listing.","storyPanels":[{"id":"beginning","enabled":true,"layout":"intro","title":"A slower beginning","body":["A place begins with a feeling. At Sodai, that feeling is the calm of arriving among palms, with the day still open before you."],"images":[{"src":"/images/nature.jpg","alt":"Sunlight over a Balinese landscape","category":"Nature"}],"caption":"An imagined retreat in Bali"},{"id":"island-fragments","enabled":true,"layout":"archive","title":"Collected moments","body":["Morning light, familiar materials, and a path that turns toward the garden."],"images":[{"src":"/images/beach.jpg","alt":"A quiet tropical shoreline under a blue sky","category":"Nature"},{"src":"/images/living.jpg","alt":"A warm, airy living room with natural materials","category":"Living"},{"src":"/images/pool.jpg","alt":"A tranquil blue swimming pool surrounded by palms","category":"Spaces"}],"caption":"Scenes from the fictional Sodai collection"},{"id":"thoughtful-spaces","enabled":true,"layout":"editorial","title":"Room to pause","body":["We imagined spaces with generous openings and quiet corners. Each villa invites the outdoors in, while leaving enough privacy to feel entirely at home.","The story is told in simple gestures: cool water after a warm day, a shaded seat, a table set for an unhurried meal."],"images":[{"src":"/images/room.jpg","alt":"A spacious bedroom with soft linen and natural light","category":"Living"}],"caption":"Soft light and natural textures"},{"id":"unhurried-rhythm","enabled":true,"layout":"quote","title":"Let the day unfold in its own time.","body":["There is no prescribed way to be here. Follow the light, rest awhile, and discover your own rhythm."],"images":[],"caption":""},{"id":"shared-table","enabled":true,"layout":"split","title":"Gather, then linger","body":["Breakfast can stretch into conversation. Later, the garden becomes a place to return to before the evening begins.","Our fictional hospitality is built around giving guests time and space, with thoughtful help close at hand."],"images":[{"src":"/images/dining.jpg","alt":"Thoughtfully prepared food served in a restaurant","category":"Living"},{"src":"/images/nature.jpg","alt":"Sunlight over a Balinese landscape","category":"Nature"}],"caption":"The pleasure of an open afternoon"},{"id":"island-culture","enabled":true,"layout":"culture","title":"A living island","body":["Bali's traditions belong to its communities. We invite visitors to approach them with curiosity, respect, and guidance from local hosts.","Its arts, ceremonies, and daily offerings make space for reflection beyond the villa walls."],"images":[{"src":"/images/beach.jpg","alt":"A quiet tropical shoreline under a blue sky","category":"Nature"}],"caption":"Explore Culture Bali"},{"id":"new-perspectives","enabled":true,"layout":"collage","title":"Always becoming","body":["The landscape changes with the hour. A familiar view feels new in rain, in morning haze, or just before dusk.","Sodai is a fictional villa demonstration, yet its invitation is real: notice the details and stay a little longer."],"images":[{"src":"/images/suite.jpg","alt":"A comfortable suite with a generous bed","category":"Living"},{"src":"/images/pool.jpg","alt":"A tranquil blue swimming pool surrounded by palms","category":"Spaces"},{"src":"/images/living.jpg","alt":"A warm, airy living room with natural materials","category":"Living"}],"caption":"Different corners, one gentle pace"},{"id":"stay-with-us","enabled":true,"layout":"closing","title":"Come as you are. Leave with time to remember.","body":["Whether you seek solitude or time together, this imagined place is here to show how a stay can feel personal.","Turn the page and find your own space."],"images":[{"src":"/images/hero.jpg","alt":"A palm-lined tropical resort with a turquoise swimming pool","category":"Spaces"}],"caption":"Sodai · an illustrative villa collection"},{"id":"a-moment-between","enabled":true,"layout":"cinematic","title":"A moment between places","body":["Where the shore meets the light, let the story linger a little longer."],"images":[{"src":"/images/beach.jpg","alt":"A quiet tropical shoreline under a blue sky","category":"Nature"}],"caption":"An image-led pause in the fictional villa story"}],"foundation":{"enabled":true,"title":"The Foundation","description":"Bali stands as a beacon of rich cultural and artistic heritage, shaped by its vibrant population and noble traditions.","hero":{"src":"/reference-foundation/e70b58d850d16896b569.webp","alt":"Balinese dance lesson at the Tandjung Sari Foundation","category":"Spaces","focalPoint":{"x":50,"y":50}},"sections":[{"id":"cultural-heritage","enabled":true,"layout":"heritage","heading":"Bali stands as a beacon of rich cultural and artistic heritage, shaped by its vibrant population and noble traditions.","archive":{"src":"/reference-foundation/29792a3478d01a6fa914.webp","alt":"Archival Balinese dancers","category":"Spaces","focalPoint":{"x":50,"y":50}},"caption":"Renowned for its resilience against colonial forces, the island embodies a paradise that fiercely preserves its unique identity within Indonesia.","statement":"Yet, a reputation—regardless of its accuracy—cannot alone uphold a culture; a strong foundation of support is essential.","body":["As Bali transforms in the face of rapid tourism development, traditional institutions that have historically supported Balinese culture must adapt. Without innovative support, such as private and corporate patronage, the island risks losing its profound aesthetic values and cultural identity.","In response to this challenge, the Tandjung Sari Foundation was established in 1987 by the visionary Wawo-Runtu family, owners of the Tandjung Sari Hotel. The foundation is dedicated to the preservation and evolution of Balinese artistic works of exceptional quality."],"teacher":{"src":"/reference-foundation/6f59373a48bf2c7aace1.webp","alt":"A teacher guiding a child through a traditional dance lesson","category":"Spaces","focalPoint":{"x":50,"y":50}}},{"id":"traditional-knowledge","enabled":true,"layout":"commitment","heading":"With a commitment to recover and promote traditional knowledge, the Tanjung Sari Foundation upholds high standards of artistic expression across fine arts, applied arts, and performing arts.","small":{"src":"/reference-foundation/7f0b73715e344302aaf5.webp","alt":"Children practising Balinese dance outdoors","category":"Spaces","focalPoint":{"x":50,"y":50}},"portrait":{"src":"/reference-foundation/6d3deb49f2e19071f138.webp","alt":"A child practising a dance gesture with a fan","category":"Spaces","focalPoint":{"x":50,"y":50}},"statement":"It nurtures creativity by merging traditional values with contemporary forms of expression."},{"id":"foundation-aims","enabled":true,"layout":"aims","heading":"The Foundation’s Aims:","entries":[{"id":"celebrate-artists","enabled":true,"body":"Identify and celebrate outstanding artists who embody high artistic standards and their representative works."},{"id":"document-artistry","enabled":true,"body":"Document their artistry through various mediums, including video, audio recordings, photography, and written records."}]},{"id":"dance-lesson-panorama","enabled":true,"layout":"widePhoto","image":{"src":"/reference-foundation/34761eefca21682077af.webp","alt":"Children practising dance together on a wooden floor","category":"Spaces","focalPoint":{"x":50,"y":50}}},{"id":"initial-programs","enabled":true,"layout":"programs","heading":"The foundation’s initial programs have breathed new life into the performing arts, revitalizing local banjar activities —","statement":"the heart of community life, where children learn to dance and where the soulful sounds of gamelan resonate.","decoration":{"src":"/reference-story/rail-emblem.svg","alt":"Coral motif","category":"Spaces"},"entries":[{"id":"banjar-sindhu","enabled":true,"image":{"src":"/reference-foundation/7d590921ccb8cf8e06ba.webp","alt":"Banjar Sindhu gamelan musicians","category":"Spaces","focalPoint":{"x":50,"y":50}},"description":"By restoring the Banjar Sindhu gamelan group and providing traditional instruments for the rare Gamelan Semar Pegulingan, the foundation is reigniting a powerful musical legacy.","placement":"low"},{"id":"traditional-teachers","enabled":true,"image":{"src":"/reference-foundation/11bd3c2f938f74942b06.webp","alt":"A dance teacher sharing traditional gestures","category":"Spaces","focalPoint":{"x":50,"y":50}},"description":"Esteemed artists inspired over one hundred local children and trainee teachers, imparting time-honored standards of excellence. They taught a range of traditional works, ensuring that these vital expressions are not lost to time.","placement":"high"},{"id":"oral-visual-history","enabled":true,"image":{"src":"/reference-foundation/8cfc4e1e57f2bc85b28c.webp","alt":"Children preparing for a ceremony","category":"Spaces","focalPoint":{"x":50,"y":50}},"description":"As teachers shared their wisdom, they contributed to an “oral and visual history,” recording their knowledge of music, instruments, dance, and the intricate arts of costuming and palm leaf decoration.","placement":"low"},{"id":"student-performances","enabled":true,"image":{"src":"/reference-foundation/27dd153c77402d97bf5f.webp","alt":"Young dancers at a student performance","category":"Spaces","focalPoint":{"x":50,"y":50}},"description":"The foundation also sponsors student performances, reintroducing these artistic standards to the community.","placement":"high"}]},{"id":"current-initiatives","enabled":true,"layout":"initiatives","heading":"Current initiatives focus on inspiring the community through the performing arts.","small":{"src":"/reference-foundation/e9b49fd06e586ada1297.webp","alt":"A young dancer performing in Balinese costume","category":"Spaces","focalPoint":{"x":50,"y":50}},"wide":{"src":"/reference-foundation/fbe2f568a96225b92f24.webp","alt":"Balinese dancers performing together in the evening","category":"Spaces","focalPoint":{"x":50,"y":50}},"portrait":{"src":"/reference-foundation/0525788b2077beba39f2.webp","alt":"A Baris dancer in elaborate traditional costume","category":"Spaces","focalPoint":{"x":50,"y":50}},"statement":"The Tandjung Sari Foundation proudly sponsors classical Balinese dance lessons for local children,","body":"offering enriching tutoring sessions twice a week on Friday and Sunday afternoons from 3:30 pm to 5:00 pm at Tandjung Sari.Furthermore, a cultural evening showcasing the talents of these children through classical Balinese dance is held every first and third Saturday of the month.","closing":"To support the preservation of these art forms, please consider making a donation to Yayasan Tandjung Bali Sari at Bank Mandiri, using account number 1450016111375 and swift code BMRIIDJA."}]},"signatureMenu":{"logo":{"src":"/reference-story/menu-logo.svg","alt":"Tandjung Sari — cape of flowers","category":"Spaces"},"photo":{"src":"/reference-story/lobby-editwebp.webp","alt":"Tandjung Sari's carved wooden lobby","category":"Spaces"},"referenceLabels":true,"introBrand":{"emblem":{"src":"/reference-story/intro-emblem.svg","alt":"Brand coral emblem","category":"Spaces"},"wordmark":{"src":"/reference-story/intro-wordmark.svg","alt":"Tandjung Sari wordmark","category":"Spaces"},"aspectRatio":1.0133333333333334,"emblemBounds":{"x":0.4605,"y":32.4,"width":66.0526,"height":66.9333}},"contactTitle":"Get in Touch","social":[],"legal":"© 2026 Sodai. Reference comparison demo.","credit":"Website by Sodai"},"signatureStory":{"railEmblem":{"src":"/reference-story/rail-emblem.svg","alt":"Tandjung Sari coral emblem","category":"Spaces"},"nextPageTitle":"Our Rooms","sections":[{"id":"story-opener","enabled":true,"layout":"opener","title":"Our Story","image":{"src":"/reference-story/lobby-editwebp.webp","alt":"Tandjung Sari's carved wooden lobby","category":"Spaces"}},{"id":"the-1960s","enabled":true,"layout":"intro","eyebrow":"Initiated in the","date":"1960’s,","body":"Tandjung Sari's logo evolved from a coral shot in front of Tandjung Sari beach, which Hans Hoefer presented to Wija as a full-page ad in the first guidebook to Bali printed in 1970. The logo practically \"designed itself\" as an extension of that shot","logo":{"src":"/reference-story/home-story-logo.svg","alt":"Tandjung Sari coral emblem","category":"Spaces"}},{"id":"sanur-timeline","enabled":true,"layout":"timeline","leadImage":{"src":"/reference-story/1960c-1jpg.jpeg","alt":"Archival photograph of the early Tandjung Sari house","category":"Spaces"},"entries":[{"id":"pax-neerlandica","image":{"src":"/reference-story/pak-wija-1-1jpg.jpeg","alt":"Archival photograph of Wija at a table","category":"Spaces"},"body":"Tourism in Bali started during the Pax Neerlandica (1908–1942) under the strict control of the Dutch colonial government after their final conquest of the island."},{"id":"sanur-hotels","image":{"src":"/reference-story/1960b-1jpg.jpeg","alt":"Archival Sanur shoreline with boats","category":"Spaces"},"body":"In time, Sanur evolved into a prominent tourist destination with the construction of the Segara Beach Hotel (which became the Segara Village) and later with the building of the InterContinental’s Bali Beach Hotel with Japanese war reparations."},{"id":"early-1960s","image":{"src":"/reference-story/timeline-interior.jpg","alt":"Archival Tandjung Sari interior with staff beneath the lamps","category":"Spaces"},"body":"If you conjure Sanur in the early 1960s when the Tandjung Sari was born, the vision you get will be a quiet one. The beach then was nearly deserted during the day, except for the coming and going of fishermen in their bright little boats and, at low tide, the harvesting of coral from the lagoon's protective reef."}],"finalImage":{"src":"/reference-story/resize-2jpg.jpeg","alt":"Early Tandjung Sari bungalow among palms","category":"Spaces"}},{"id":"founding","enabled":true,"layout":"founding","heading":"The Tandjung Sari did not intend to become the seminal boutique hotel of tropical Asia.","body":["It began as a place to spend the night for its owner, Wija Wawo-Runtu (1926 - 2001), and his family when they visited Bali from Jakarta on shopping trips for their antique business.","The Wawo-Runtu's little paradise attracted friends from Jakarta, and by 1962, they had four small bungalows for friends who wished to visit Bali.","Within a few years, Tandjung Sari was internationally renowned among smart people as the place to stay if you could get in."],"image":{"src":"/reference-story/resize-3jpg.jpeg","alt":"Tandjung Sari's beachfront terrace","category":"Spaces"},"rightHeading":"Bali's tourism industry began to flourish, leading to the expansion of the island's international airport, which was officially inaugurated as Bali International Airport Ngurah Rai in August 1969.","insetImage":{"src":"/reference-story/frame-38608png.png","alt":"Archival view of Sanur's tourism development","category":"Spaces"},"rightCaption":"As tourism continued to grow, Sanur became the most prestigious address on the island."},{"id":"intimacy-with-bali","enabled":true,"layout":"redEditorial","image":{"src":"/reference-story/resize-1jpg.jpeg","alt":"Red-toned photograph of traditional Balinese architecture","category":"Spaces"},"heading":"Wija understood that visitors wanted intimacy with Bali.","body":["They wanted to feel the air of Bali on their skin and to live in what they imagined was a Balinese way but more comfortably."],"alignment":"low"},{"id":"batujimbar-estate","enabled":true,"layout":"architecture","image":{"src":"/reference-story/15-1png.png","alt":"Two archival photographs of Tandjung Sari architecture","category":"Spaces"},"heading":"The success of the Tandjung Sari convinced him that the concept could be taken to a larger scale.","caption":"That inspired the development of the Batujimbar Estate.","body":["In February 1974, Indonesia hosted the Pacific Asia Travel Association (PATA) conference, and a few months earlier, in October 1973, Bali Hyatt was completed.","On a par with the expanded Tandjung Sari, with its sixteen new bungalows normally full, the restaurant was a powerful magnet, too. The Tandjung Sari's famous cuisine captivated Craig Claiborne, a food writer and former editor of The New York Times, who devoted a chapter to Tatie Wawo-Runtu's recipe for Soto Ayam.","When the structures were still new and the hotel was doing very well, there were lots of celebrated guests: Calvin Klein, Kirk Douglas, David Bowie, Mick Jagger, Queen Ingrid of Denmark, Margaret Mead, Ingrid Bergman, Annie Lennox, Ringo Starr, Yoko Ono, Paul Getty Jr. and his wife Talitha, and Lionel Poilâne."]},{"id":"cultural-performance","enabled":true,"layout":"redEditorial","image":{"src":"/reference-story/snapinstaapp27269686895319103558308643829194325254783n1080-1png.png","alt":"Young Balinese dancers in gold performance dress","category":"Spaces"},"heading":"The Tandjung Sari cultural performance has significantly contributed to the place's legend.","body":["Numerous cultural activities were initiated, and the Tandjung Sari Foundation was established in September 1987 to formalize the commitment to preserve classical dance and other aspects of Balinese culture.","Dance lessons are still regularly scheduled on Friday and Sunday afternoons to tutor children from the local banjar, and their performances take place on stage every first and third Saturday evening of the month."],"alignment":"high"},{"id":"gentle-renaissance","enabled":true,"layout":"laterHistory","image":{"src":"/reference-story/20220726133315-1jpg.jpeg","alt":"Vintage vehicle outside Tandjung Sari","category":"Spaces"},"decoration":{"src":"/reference-story/later-emblem.svg","alt":"Coral motif","category":"Spaces"},"heading":"For years, the hotel had been coasting from the boom years of the 1970s and '80s, shocked by the impact of the 1991 Gulf War, the 1997 financial crisis, Wija Wawo-Runtu's passing, and the 2003 SARS epidemic.","note":"Then came the gentle renaissance. In 2005, the Tandjung Sari underwent its first renovations","detailImage":{"src":"/reference-story/pillar-ornamentsjpg.jpeg","alt":"Carved Balinese architectural pillar","category":"Spaces"},"bookHeading":"At the age of fifty in 2012, the hotel was deeply rejuvenated from within. To celebrate the golden anniversary of Tandjung Sari, the remarkable book Tandjung Sari—A Magical Door to Bali was launched.","body":["The book tells how the hotel grew, the challenges and triumphs, and the people who made it happen. The book has become known for telling the early '60s tourism story in Sanur and enticing readers to dig more into Balinese architecture.","Another step of the 55-year milestone (2017) was celebrated with the Tandjung Sari documentary film, which portrayed the journey from its early days."]},{"id":"a-magical-door","enabled":true,"layout":"bookClosing","image":{"src":"/reference-story/dsc06901-1png.png","alt":"Tandjung Sari: A Magical Door to Bali book","category":"Spaces"},"body":["What drew people was the Tandjung Sari's judicious blend of the lowkey and luxurious. The architecture was simple, using local materials and Balinese building techniques, yet the location was on a prime beachfront with wonderful gardens. The rooms were furnished with Balinese antiques, and the hospitality was warm and sophisticated.","Guests felt they were experiencing a highly refined version of \"the real Bali\" with all its sounds and silences, deep perfumes, bare-handedness and hilarity, and powerful enchantment at the edge of a spangled sea."],"heading":"The Tandjung Sari remains a treasure today, still run by the Wawo-Runtu family, discreet and elegantly modest, an ageless beauty."},{"enabled":false,"source":"","poster":null,"id":"documentary-still","layout":"video"}],"video":{"enabled":false,"source":"","poster":null}},"culture":{"enabled":true,"hero":{"src":"/reference-culture/ab393444c4123aa8c18b.webp","alt":"Balinese ceremonial procession","category":"Living"},"title":"Cultures","introTitle":"Bali, with its enchanting charm, presents a tapestry of unique and authentic cultural experiences waiting to be discovered across the island.","intro":["Some are just around the corner, while others invite you to embark on an adventure, requiring a tour or transportation to reach their distant beauty.","The Balinese cultural calendar, following the Saka/local calendar, unfolds throughout the year, offering a journey of inspiration and wonder."],"introImages":[{"src":"/reference-culture/0b53fbd7e1c7785fafe7.webp","alt":"Map of Bali","category":"Living"},{"src":"/reference-culture/80456c8e17d1b49c9da0.webp","alt":"Balinese ceremonial carving","category":"Living"}],"entries":[{"id":"galungan","enabled":true,"slug":"galungan","title":"Galungan","summary":"The Galungan holiday, one of Bali’s most important, falls once every 210 days, in the Balinese week of Dunggulan, always on a Wednesday.","image":{"src":"/reference-culture/d1861ff92e521db9b46a.webp","alt":"Galungan","category":"Living"},"heading":"The essence of Galungan is to defeat evil in oneself so that we can live in peace and harmony.","body":["According to old written records, Galungan was first celebrated on the 15th full moon of the year 804 in the Balinese Saka calendar, or 882 AD, to honor the triumph of Lord Indra over the evil king Mayadenawa, seen as a victory of good over evil. The term Galungan comes from Old Javanese and means ‘battle, combat’."],"signature":{"hero":{"src":"/reference-culture/d1861ff92e521db9b46a.webp","alt":"Galungan","category":"Living"},"nextSlug":"kuningan-and-mekotek","sections":[{"id":"galungan-portrait-editorial","enabled":true,"layout":"portraitEditorial","image":{"src":"/reference-culture/e0b55b7a8293115c0db1.webp","alt":"Galungan editorial photograph","category":"Living"},"heading":"The essence of Galungan is to defeat evil in oneself so that we can live in peace and harmony.","body":["According to old written records, Galungan was first celebrated on the 15th full moon of the year 804 in the Balinese Saka calendar, or 882 AD, to honor the triumph of Lord Indra over the evil king Mayadenawa, seen as a victory of good over evil. The term Galungan comes from Old Javanese and means ‘battle, combat’."]},{"id":"galungan-red-editorial","enabled":true,"layout":"redOverlay","image":{"src":"/reference-culture/dfe0b83899ba31583d4f.webp","alt":"Galungan cultural ceremony","category":"Living"},"heading":"On Galungan day, the island takes on an even more magical atmosphere","body":["with the towering penjor (decorated bamboo poles) standing at the gate of every house.","The Balinese believe that the spirits of the ancestors return home during Galungan. Therefore, prayers and offerings are prepared to welcome the spirits."]}]}},{"id":"kuningan-and-mekotek","enabled":true,"slug":"kuningan-and-mekotek","title":"Kuningan & Mekotek","summary":"Kuningan is a Balinese holy day celebrated ten days after Galungan. It derives from ka-uningan, meaning wisdom, and the ritual aim is to attain spiritual elevation through introspection.","image":{"src":"/reference-culture/5b7d0c5e7dac9045e6e5.webp","alt":"Kuningan & Mekotek","category":"Living"},"heading":"Kuningan is a Balinese holy day celebrated ten days after Galungan.","body":["On Kuningan day, we can witness an unusual rite called mekotekan in the village of Munggu, once the seat of the powerful kingdom of Mengwi. In this purification ritual, the young men of the village each carry a pole, from two to 3.5 meters long, made of pulet wood. They process around the village to the temple Pura Luhur Beten Bingin, where they pile the poles together to create a pyramid-like construction, in which teams compete to climb."],"signature":{"hero":{"src":"/reference-culture/5b7d0c5e7dac9045e6e5.webp","alt":"Kuningan & Mekotek","category":"Living"},"nextSlug":"melasti","sections":[{"id":"kuningan-and-mekotek-portrait-editorial","enabled":true,"layout":"portraitEditorial","image":{"src":"/reference-culture/3d18647fe94d9db35207.webp","alt":"Kuningan & Mekotek editorial photograph","category":"Living"},"heading":"Kuningan is a Balinese holy day celebrated ten days after Galungan.","body":["On Kuningan day, we can witness an unusual rite called mekotekan in the village of Munggu, once the seat of the powerful kingdom of Mengwi. In this purification ritual, the young men of the village each carry a pole, from two to 3.5 meters long, made of pulet wood. They process around the village to the temple Pura Luhur Beten Bingin, where they pile the poles together to create a pyramid-like construction, in which teams compete to climb."]},{"id":"kuningan-and-mekotek-red-editorial","enabled":true,"layout":"redOverlay","image":{"src":"/reference-culture/a03e07274ca0e02df89f.webp","alt":"Kuningan & Mekotek cultural ceremony","category":"Living"},"heading":"As the sticks crash together, they make a sound like tek tek tek, thus the term mekotekan.","body":["The rite is said to have roots in the victory of Mengwi over Blambangan in East Java in the 17th century. It is held to honor ancestral heroes, and with the hope of protection from unexpected misfortune."]}]}},{"id":"nyepi","enabled":true,"slug":"nyepi","title":"Nyepi","summary":"The Balinese New Year is known as Nyepi and is celebrated according to the Saka lunar calendar, on the dark of the moon of the spring equinox, usually falling in March or early April.","image":{"src":"/reference-culture/90ff749fbcbbd0df686d.webp","alt":"Nyepi","category":"Living"},"heading":"The word nyepi comes from ‘sepi’, meaning ‘empty’.","body":["Although Nyepi is a traditional Balinese Hindu celebration, it has become a national holiday in Indonesia. The folk idea is to make the world appear as if deserted, so that disruptive spirits will abandon the island and look elsewhere to cause mischief."],"signature":{"hero":{"src":"/reference-culture/90ff749fbcbbd0df686d.webp","alt":"Nyepi","category":"Living"},"nextSlug":"piodalan","sections":[{"id":"nyepi-portrait-editorial","enabled":true,"layout":"portraitEditorial","image":{"src":"/reference-culture/f2dbeec750059c34c5e5.webp","alt":"Nyepi editorial photograph","category":"Living"},"heading":"The word nyepi comes from ‘sepi’, meaning ‘empty’.","body":["Although Nyepi is a traditional Balinese Hindu celebration, it has become a national holiday in Indonesia. The folk idea is to make the world appear as if deserted, so that disruptive spirits will abandon the island and look elsewhere to cause mischief."]},{"id":"nyepi-red-editorial","enabled":true,"layout":"redOverlay","image":{"src":"/reference-culture/a859db4cc69dde54c8db.webp","alt":"Nyepi cultural ceremony","category":"Living"},"heading":"There is no traffic on the roads, and in the evening, lights are not to be turned on. Ngurah Rai Airport is closed to all flights.","body":["On Nyepi, everyone is asked to stay inside their\nhome compound for 24 hours, from dawn to the following dawn. Visitors, too,\nmust comply with this custom and are asked not to stray from the hotel grounds.Many visitors remark on the extraordinary quiet and peacefulness of this day of silence.","The Balinese people treat Nyepi as an opportunity to meditate and fast. The importance of this holy day is to detach oneself from the world and seek inward peace."]}]}},{"id":"melasti","enabled":true,"slug":"melasti","title":"Melasti","summary":"Three days before Nyepi, a large purification\nceremony called melasti is held by villages all over Bali.","image":{"src":"/reference-culture/ab5435506ce86cc67fa9.webp","alt":"Melasti","category":"Living"},"heading":"The sea is a significant element for Balinese Hindus, who believe that it is the realm where all spiritual impurities are destroyed.","body":["Each household erects a triangular altar for\nofferings by the roadside, and holy objects from the temples are brought in\nprocession to the sea to be cleansed in a special ritual.","Massive community processions gather on beaches\nall around the island to participate in this ritual cleansing. Guests can witness this inspiring ceremony on Sanur Beach."],"signature":{"hero":{"src":"/reference-culture/ab5435506ce86cc67fa9.webp","alt":"Melasti","category":"Living"},"nextSlug":"ogoh-ogoh","sections":[{"id":"melasti-portrait-editorial","enabled":true,"layout":"portraitEditorial","image":{"src":"/reference-culture/7e5c7ef865bbd2c6bfc9.webp","alt":"Melasti editorial photograph","category":"Living"},"heading":"The sea is a significant element for Balinese Hindus, who believe that it is the realm where all spiritual impurities are destroyed.","body":["Each household erects a triangular altar for\nofferings by the roadside, and holy objects from the temples are brought in\nprocession to the sea to be cleansed in a special ritual.","Massive community processions gather on beaches\nall around the island to participate in this ritual cleansing. Guests can witness this inspiring ceremony on Sanur Beach."]},{"id":"melasti-red-editorial","enabled":true,"layout":"redOverlay","image":{"src":"/reference-culture/f9c2fa78bbd9daac70fe.webp","alt":"Melasti cultural ceremony","category":"Living"},"heading":"Guests can witness this inspiring ceremony on Sanur Beach.","body":["Hindus people believe that it is the realm where all spiritual impurities are destroyed. Massive community processions gather on beaches all around the island to participate in this ritual cleansing."]}]}},{"id":"ogoh-ogoh","enabled":true,"slug":"ogoh-ogoh","title":"Ogoh-ogoh","summary":"In the evening of Pengrupukan, the day before\nNyepi, villages parade ogoh-ogoh—giant effigies of demons, designed and\nbuilt by the youth of each community.","image":{"src":"/reference-culture/b80d8290bd0c4d05b2ef.webp","alt":"Ogoh-ogoh","category":"Living"},"heading":"The ogoh-ogoh parade is intense—noisy and wild, accompanied by torches and orchestras of cymbals and gongs.","body":["In household ceremonies, the people will bang\ngongs, pots and pans, and bamboo sticks to chase the evil spirits from the\nisland.","It takes place in village streets and centers. Traditionally, the procession ends up at the cemetery where the effigies are burned, and all the negative energies are dispersed, preparing the way for the peace of Nyepi."],"signature":{"hero":{"src":"/reference-culture/b80d8290bd0c4d05b2ef.webp","alt":"Ogoh-ogoh","category":"Living"},"nextSlug":"nyepi","sections":[{"id":"ogoh-ogoh-portrait-editorial","enabled":true,"layout":"portraitEditorial","image":{"src":"/reference-culture/dcd762c7cf9356097560.webp","alt":"Ogoh-ogoh editorial photograph","category":"Living"},"heading":"The ogoh-ogoh parade is intense—noisy and wild, accompanied by torches and orchestras of cymbals and gongs.","body":["In household ceremonies, the people will bang\ngongs, pots and pans, and bamboo sticks to chase the evil spirits from the\nisland.","It takes place in village streets and centers. Traditionally, the procession ends up at the cemetery where the effigies are burned, and all the negative energies are dispersed, preparing the way for the peace of Nyepi."]},{"id":"ogoh-ogoh-red-editorial","enabled":true,"layout":"redOverlay","image":{"src":"/reference-culture/0079bad9b0beec2dfd26.webp","alt":"Ogoh-ogoh cultural ceremony","category":"Living"},"heading":"Creating an ogoh-ogoh—usually from bamboo, wood, and paper—takes two to three months and involves all the men in the banjar, or community unit.","body":["Some ogoh-ogoh have mechanized movements. Every year there is creative suspense to see what new forms will emerge and what materials are used. Recently there was a trend for dried banana leaves and used plastic bottles."]}]}},{"id":"piodalan","enabled":true,"slug":"piodalan","title":"Piodalan","summary":"A piodalan is a temple’s anniversary,\nwhen the deities are believed to come down from heaven to the temple shrines,\npartake of offerings, and convey blessings through the medium of holy water.","image":{"src":"/reference-culture/cf5a2c6bca0d3d5f8372.webp","alt":"Piodalan","category":"Living"},"heading":"Temple anniversaries date from their founding and occur all around the year, whether on the 210-day Balinese calendar or the Saka lunar calendar.","body":["The gods are welcomed with offerings of food, flowers, traditional music, and dances. People wear their best temple clothes, and it is a very happy time."],"signature":{"hero":{"src":"/reference-culture/cf5a2c6bca0d3d5f8372.webp","alt":"Piodalan","category":"Living"},"nextSlug":"bali-art-festival","sections":[{"id":"piodalan-portrait-editorial","enabled":true,"layout":"portraitEditorial","image":{"src":"/reference-culture/eb27cd01d7bac1b2fc45.webp","alt":"Piodalan editorial photograph","category":"Living"},"heading":"Temple anniversaries date from their founding and occur all around the year, whether on the 210-day Balinese calendar or the Saka lunar calendar.","body":["The gods are welcomed with offerings of food, flowers, traditional music, and dances. People wear their best temple clothes, and it is a very happy time."]},{"id":"piodalan-red-editorial","enabled":true,"layout":"redOverlay","image":{"src":"/reference-culture/ff289cfb6703228b333f.webp","alt":"Piodalan cultural ceremony","category":"Living"},"heading":"The piodalan ceremony is also held at Pura Tandjung Sari—the beachfront temple for which the hotel is named—on Purnama Sasih Kedasa.","body":["Purnama sasih kedasa is the full moon of the tenth month of the Saka lunar calendar. It is a particularly holy day in Bali and usually falls in March or April.","You are welcome to witness this beautiful religious occasion. As with any Balinese ceremony, a sarong, and a sash, with a kebaya blouse for women, are required to be worn by those attending the ceremony."]}]}},{"id":"bali-art-festival","enabled":true,"slug":"bali-art-festival","title":"Bali Art Festival","summary":"The island’s largest and most spectacular\ncultural event, the Bali Arts Festival (Pesta Kesenian Bali), is an annual\nprogram organized by the government of Bali Province.","image":{"src":"/reference-culture/7403d9c7763d195fe7f5.webp","alt":"Bali Art Festival","category":"Living"},"heading":"The festival is held in Denpasar at the Werdhi Budaya Art Centre.","body":["It lasts for a month and takes place every year from mid-June to the middle of July. It showcases the variety and richness of\nperforming arts traditions from the different regions in Bali, as well as other\nprovinces in Indonesia and a number of foreign countries."],"signature":{"hero":{"src":"/reference-culture/7403d9c7763d195fe7f5.webp","alt":"Bali Art Festival","category":"Living"},"nextSlug":"perang-pandan-and-ayunan-jantra","sections":[{"id":"bali-art-festival-portrait-editorial","enabled":true,"layout":"portraitEditorial","image":{"src":"/reference-culture/a83d7f3c72e417a26e15.webp","alt":"Bali Art Festival editorial photograph","category":"Living"},"heading":"The festival is held in Denpasar at the Werdhi Budaya Art Centre.","body":["It lasts for a month and takes place every year from mid-June to the middle of July. It showcases the variety and richness of\nperforming arts traditions from the different regions in Bali, as well as other\nprovinces in Indonesia and a number of foreign countries."]},{"id":"bali-art-festival-red-editorial","enabled":true,"layout":"redOverlay","image":{"src":"/reference-culture/55b03ac5a999ba0999e7.webp","alt":"Bali Art Festival cultural ceremony","category":"Living"},"heading":"On the opening day, an enormous parade of all the performing groups is held in Renon, Denpasar.","body":["The festival is traditionally opened by the President of Indonesia."]}]}},{"id":"perang-pandan-and-ayunan-jantra","enabled":true,"slug":"perang-pandan-and-ayunan-jantra","title":"Perang Pandan & Ayunan Jantra","summary":"The Bali Aga village of Tenganan Dauh Tukad in Karangasem Regency has a unique tradition of a ritual battle with spiny pandan leaves, known as mekare-kare or mageret pandan.","image":{"src":"/reference-culture/d44b7226bb8f18301535.webp","alt":"Perang Pandan & Ayunan Jantra","category":"Living"},"heading":"The Perang Pandan ritual battle is carried out to honor the god Indra, the deity of war, and is part of the Sasih Sembah ceremonies, an important series of religious celebrations in Tenganan Village.","body":["This ceremony lasts for two days, held every fifth month or Sasih Kalima on Tenganan’s village calendar (around June)."],"signature":{"hero":{"src":"/reference-culture/d44b7226bb8f18301535.webp","alt":"Perang Pandan & Ayunan Jantra","category":"Living"},"nextSlug":"purnama-and-tilem","sections":[{"id":"perang-pandan-and-ayunan-jantra-portrait-editorial","enabled":true,"layout":"portraitEditorial","image":{"src":"/reference-culture/f5dc41504a0b1b70bbd4.webp","alt":"Perang Pandan & Ayunan Jantra editorial photograph","category":"Living"},"heading":"The Perang Pandan ritual battle is carried out to honor the god Indra, the deity of war, and is part of the Sasih Sembah ceremonies, an important series of religious celebrations in Tenganan Village.","body":["This ceremony lasts for two days, held every fifth month or Sasih Kalima on Tenganan’s village calendar (around June)."]},{"id":"perang-pandan-and-ayunan-jantra-red-editorial","enabled":true,"layout":"redOverlay","image":{"src":"/reference-culture/8e5c0cef5f24f749bad6.webp","alt":"Perang Pandan & Ayunan Jantra cultural ceremony","category":"Living"},"heading":"Following the Perang Pandan, the Ayunan Jantra (on a wooden circular swing) will grace the late afternoon.","body":["This tradition describes the continuous life cycle, inspiring young people to embrace the journey ahead. The swing’s ups and downs are a powerful reminder to prepare for the realities that await.","Please contact our reservations desk if you are interested in witnessing these cultural events."]}]}},{"id":"purnama-and-tilem","enabled":true,"slug":"purnama-and-tilem","title":"Purnama & Tilem","summary":"The full moon (Purnama) and the dark of the moon (Tilem) are always sacred days for Balinese Hindus.","image":{"src":"/reference-culture/121cce936dd20c4f007d.webp","alt":"Purnama & Tilem","category":"Living"},"heading":"Purnama is generally marked by a high tide.","body":["To protect the self from negative effects, people are advised to take time for introspection and self-purification."],"signature":{"hero":{"src":"/reference-culture/121cce936dd20c4f007d.webp","alt":"Purnama & Tilem","category":"Living"},"nextSlug":"offerings","sections":[{"id":"purnama-and-tilem-portrait-editorial","enabled":true,"layout":"portraitEditorial","image":{"src":"/reference-culture/aef29ec2291b9a602257.webp","alt":"Purnama & Tilem editorial photograph","category":"Living"},"heading":"Purnama is generally marked by a high tide.","body":["To protect the self from negative effects, people are advised to take time for introspection and self-purification."]},{"id":"purnama-and-tilem-red-editorial","enabled":true,"layout":"redOverlay","image":{"src":"/reference-culture/902e495f74f887d9d1e4.webp","alt":"Purnama & Tilem cultural ceremony","category":"Living"},"heading":"Tilem is the darkest night of the month.","body":["On Purnama and on Tilem, special offerings are placed in significant places around houses and temples and in local shrines everywhere.","Both stages of the moon are believed to have\nambivalent mystical energy."]}]}},{"id":"offerings","enabled":true,"slug":"offerings","title":"Offerings","summary":"In Bali, all religious rites, large and small, are carried out with offerings, called banten in Balinese.","image":{"src":"/reference-culture/b6dd788b515d2eeb761b.webp","alt":"Offerings","category":"Living"},"heading":"The knowledge of offerings is held by priestly families, and the art of making them is traditionally carried out by women, taught from one generation to the next.","body":["Most basically, these are symbolic amounts of food placed on a leaf container. But the variety of food and leaf containers—as well as the flowers and palm leaf ornaments, cut and pinned in myriad ways—is uncountably complex."],"signature":{"hero":{"src":"/reference-culture/b6dd788b515d2eeb761b.webp","alt":"Offerings","category":"Living"},"sections":[{"id":"offerings-portrait-editorial","enabled":true,"layout":"portraitEditorial","image":{"src":"/reference-culture/1dda2b9e8893fc7ad095.webp","alt":"Offerings editorial photograph","category":"Living"},"heading":"The knowledge of offerings is held by priestly families, and the art of making them is traditionally carried out by women, taught from one generation to the next.","body":["Most basically, these are symbolic amounts of food placed on a leaf container. But the variety of food and leaf containers—as well as the flowers and palm leaf ornaments, cut and pinned in myriad ways—is uncountably complex."]},{"id":"offerings-red-editorial","enabled":true,"layout":"redOverlay","image":{"src":"/reference-culture/717c76a00ce0c9ee3369.webp","alt":"Offerings cultural ceremony","category":"Living"},"heading":"It is the profusion of offerings that give Bali its particular festive look and mystical feel.","body":["Each offering has a special form and meaning according to the custom of the particular place, and each one is offered with incense, holy water, and a prayer. And there is no room for improvisation.","Guests interested in learning Balinese offering-making can book through our reservations desk."]}]}}]},"address":"Ubud, Bali, Indonesia · illustrative location","email":"stay@example.com","mapUrl":"https://www.google.com/maps/search/?api=1&query=Ubud+Bali","hero":{"src":"/reference-story/lobby-editwebp.webp","alt":"Tandjung Sari's carved wooden lobby","category":"Spaces"},"gallery":[{"src":"/images/hero.jpg","alt":"A palm-lined tropical resort with a turquoise swimming pool","category":"Spaces"},{"src":"/images/room.jpg","alt":"A spacious bedroom with soft linen and natural light","category":"Living"},{"src":"/images/pool.jpg","alt":"A tranquil blue swimming pool surrounded by palms","category":"Spaces"},{"src":"/images/living.jpg","alt":"A warm, airy living room with natural materials","category":"Living"},{"src":"/images/dining.jpg","alt":"Thoughtfully prepared food served in a restaurant","category":"Living"},{"src":"/images/nature.jpg","alt":"Sunlight over a Balinese landscape","category":"Nature"},{"src":"/images/beach.jpg","alt":"A quiet tropical shoreline under a blue sky","category":"Nature"},{"src":"/images/suite.jpg","alt":"A comfortable suite with a generous bed","category":"Living"}],"signatureGallery":{"enabled":true,"title":"Gallery","description":"Photographs of Tandjung Sari bungalows, dining, gardens and island life.","categories":[{"id":"bungalows","label":"Bungalows","enabled":true},{"id":"dining","label":"Dining","enabled":true}],"items":[{"id":"photo-04f0fe2c9de4be229f4b","enabled":true,"image":{"src":"/reference-gallery/04f0fe2c9de4be229f4b.webp","alt":"Shrimp and dumplings on a plate over grey timber","category":"Living"},"width":976,"height":549,"viewerOrder":65,"categories":["dining"]},{"id":"photo-c001d1deb663281f0733","enabled":true,"image":{"src":"/reference-gallery/c001d1deb663281f0733.webp","alt":"Dumplings and orange flowers on a white plate","category":"Living"},"width":549,"height":976,"viewerOrder":63,"categories":["dining"]},{"id":"photo-2bd1c5d15e5d3544d7b3","enabled":true,"image":{"src":"/reference-gallery/2bd1c5d15e5d3544d7b3.webp","alt":"Yellow rice cone and satay with orange flowers","category":"Living"},"width":549,"height":976,"viewerOrder":66,"categories":["dining"]},{"id":"photo-5e9f85bcca3c2ee9a3de","enabled":true,"image":{"src":"/reference-gallery/5e9f85bcca3c2ee9a3de.webp","alt":"Green salad and Parmesan in a green bowl","category":"Living"},"width":976,"height":549,"viewerOrder":68,"categories":["dining"]},{"id":"photo-b7346f44eb1f9f39e8b3","enabled":true,"image":{"src":"/reference-gallery/b7346f44eb1f9f39e8b3.webp","alt":"Traditional rice and meat on a woven placemat","category":"Living"},"width":976,"height":549,"viewerOrder":70,"categories":["dining"]},{"id":"photo-4e4fabfbd1bb581a6f79","enabled":true,"image":{"src":"/reference-gallery/4e4fabfbd1bb581a6f79.webp","alt":"Beef medallion with mashed potato and vegetables","category":"Living"},"width":549,"height":976,"viewerOrder":64,"categories":["dining"]},{"id":"photo-d98daa940aa3bf676165","enabled":true,"image":{"src":"/reference-gallery/d98daa940aa3bf676165.webp","alt":"Yellow rice cone with vegetables and satay","category":"Living"},"width":976,"height":549,"viewerOrder":67,"categories":["dining"]},{"id":"photo-700e120cd6be584f554a","enabled":true,"image":{"src":"/reference-gallery/700e120cd6be584f554a.webp","alt":"Shaded garden restaurant tables","category":"Living"},"width":976,"height":549,"viewerOrder":74,"categories":["dining"]},{"id":"photo-2b2f87a2e5bd4a2ef44e","enabled":true,"image":{"src":"/reference-gallery/2b2f87a2e5bd4a2ef44e.webp","alt":"Soup and side dishes with marigolds","category":"Living"},"width":549,"height":976,"viewerOrder":71,"categories":["dining"]},{"id":"photo-890434f12d9de09f060c","enabled":true,"image":{"src":"/reference-gallery/890434f12d9de09f060c.webp","alt":"Dressing being spooned onto pasta","category":"Living"},"width":549,"height":976,"viewerOrder":73,"categories":["dining"]},{"id":"photo-f8226214d38c072cd03e","enabled":true,"image":{"src":"/reference-gallery/f8226214d38c072cd03e.webp","alt":"Restaurant courtyard surrounded by tropical gardens","category":"Living"},"width":976,"height":549,"viewerOrder":72,"categories":["dining"]},{"id":"photo-275711ba72b75912e84e","enabled":true,"image":{"src":"/reference-gallery/275711ba72b75912e84e.webp","alt":"Meal and juice on a white bistro table","category":"Living"},"width":549,"height":976,"viewerOrder":69,"categories":["dining"]},{"id":"photo-e1ffbbb3eeb226432f89","enabled":true,"image":{"src":"/reference-gallery/e1ffbbb3eeb226432f89.webp","alt":"Pasta bowl held in front of green leaves","category":"Living"},"width":549,"height":976,"viewerOrder":76,"categories":["dining"]},{"id":"photo-50cd46419aada4f98fb7","enabled":true,"image":{"src":"/reference-gallery/50cd46419aada4f98fb7.webp","alt":"Thatched garden pavilion beside a bungalow","category":"Living"},"width":976,"height":549,"viewerOrder":79,"categories":["dining"]},{"id":"photo-7bee50c19bb8f6c1bde8","enabled":true,"image":{"src":"/reference-gallery/7bee50c19bb8f6c1bde8.webp","alt":"Breakfast pastries and a white coffee cup","category":"Living"},"width":549,"height":976,"viewerOrder":81,"categories":["dining"]},{"id":"photo-333cfab0ad4f357a24a3","enabled":true,"image":{"src":"/reference-gallery/333cfab0ad4f357a24a3.webp","alt":"White round tables and wooden chairs","category":"Living"},"width":976,"height":549,"viewerOrder":75,"categories":["dining"]},{"id":"photo-0bfbd62601aa775d9a48","enabled":true,"image":{"src":"/reference-gallery/0bfbd62601aa775d9a48.webp","alt":"Swimming pool beside a stone garden","category":"Living"},"width":549,"height":976,"viewerOrder":77,"categories":["dining"]},{"id":"photo-a31aded63a0b7b264c75","enabled":true,"image":{"src":"/reference-gallery/a31aded63a0b7b264c75.webp","alt":"Tea and sandwiches in white crockery","category":"Living"},"width