ws"]},{"id":"photo-8160fdf44f20745ab16e","enabled":true,"image":{"src":"/reference-gallery/8160fdf44f20745ab16e.webp","alt":"Beach umbrella seen through a shaded interior","category":"Living"},"width":549,"height":823,"viewerOrder":137,"categories":["dining"]},{"id":"photo-fbd229636056df7e9c57","enabled":true,"image":{"src":"/reference-gallery/fbd229636056df7e9c57.webp","alt":"Yellow lanterns among palms at dusk","category":"Living"},"width":549,"height":823,"viewerOrder":138,"categories":["dining"]},{"id":"photo-03a2a2e329372f53a165","enabled":true,"image":{"src":"/reference-gallery/03a2a2e329372f53a165.webp","alt":"Two-storey building beside the swimming pool","category":"Spaces"},"width":549,"height":823,"viewerOrder":155,"categories":[]},{"id":"photo-0f55f446f0178fab1163","enabled":true,"image":{"src":"/reference-gallery/0f55f446f0178fab1163.webp","alt":"Sunrise across beach parasols and the sea","category":"Spaces"},"width":976,"height":651,"caption":"description","viewerOrder":150,"categories":[]},{"id":"photo-d590838948e82e21fe07","enabled":true,"image":{"src":"/reference-gallery/d590838948e82e21fe07.webp","alt":"Lone palm and white beach umbrella","category":"Living"},"width":976,"height":651,"viewerOrder":142,"categories":["dining"]},{"id":"photo-8c4906a5234e09de7069","enabled":true,"image":{"src":"/reference-gallery/8c4906a5234e09de7069.webp","alt":"Patterned cushion and cane chair in a bungalow","category":"Spaces"},"width":549,"height":823,"viewerOrder":143,"categories":["bungalows"]},{"id":"photo-7c136d124bd3f72d86fb","enabled":true,"image":{"src":"/reference-gallery/7c136d124bd3f72d86fb.webp","alt":"White bungalow porch surrounded by flowers","category":"Spaces"},"width":549,"height":823,"viewerOrder":153,"categories":[]},{"id":"photo-e71106ec6e875202566f","enabled":true,"image":{"src":"/reference-gallery/e71106ec6e875202566f.webp","alt":"Balinese musicians playing gamelan","category":"Spaces"},"width":976,"height":651,"viewerOrder":145,"categories":[]},{"id":"photo-16edeb6333e7831e4797","enabled":true,"image":{"src":"/reference-gallery/16edeb6333e7831e4797.webp","alt":"Stone garden basin amid tropical plants","category":"Spaces"},"width":549,"height":823,"viewerOrder":149,"categories":[]},{"id":"photo-722252c241ca10c517f7","enabled":true,"image":{"src":"/reference-gallery/722252c241ca10c517f7.webp","alt":"Sunrise silhouettes of palms and a beach visitor","category":"Spaces"},"width":549,"height":823,"viewerOrder":148,"categories":[]},{"id":"photo-b61e9790c80c034c2773","enabled":true,"image":{"src":"/reference-gallery/b61e9790c80c034c2773.webp","alt":"Living room with polished wood floor and open windows","category":"Spaces"},"width":549,"height":823,"viewerOrder":156,"categories":["bungalows"]},{"id":"photo-57ae197b044192338acf","enabled":true,"image":{"src":"/reference-gallery/57ae197b044192338acf.webp","alt":"Framed painting on a stone wall beside a palm","category":"Spaces"},"width":549,"height":823,"viewerOrder":154,"categories":[]}]},"amenities":["Private pool","Daily breakfast","Garden living","Thoughtful service","Fast Wi-Fi","Airport transfer"],"rooms":[{"id":"rooms-village-bungalow","slug":"village-bungalow","title":"Village Bungalow","description":"Our Village Bungalows, which comprise sixteen large, charming cottages, are some of the first structures designed by Pak Wija. They are inspired by traditional Balinese architecture, with a thatched roof and cool, air-conditioned interiors.","image":{"src":"/reference-rooms/ec7335ef6b985507.webp","alt":"Village Bungalow","category":"Spaces"},"capacity":2,"area":45,"facilities":["Cotton shirt, sarong & sun hat","Bathub","Hairdryer","Minibar","Safety deposit box","Tea/coffee maker","Telephone","Wifi"],"inclusions":["Daily ala carte Breakfast in the seaside restaurant","Two bottles of water provided in the room complimentary  daily","Cold towel upon arrival","Welcome drink at the beachfront bar"],"signature":{"hero":{"src":"/reference-rooms/1cf3dd4a833ce838.webp","alt":"Village Bungalow exterior","category":"Spaces"},"heading":"Our Village Bungalows, which comprise sixteen large, charming cottages, are some of the first structures designed by Pak Wija. They are inspired by traditional Balinese architecture, with a thatched roof and cool, air-conditioned interiors.","body":["Each group of four bungalows is arranged in a configuration resembling the Hindu cosmic wheel, connected at the center to a vintage balé kulkul tower.   The spacious bedroom and living area includes a king-sized bed and two sofas that can convert into single beds. The large bathroom leads to an outdoor shower in a secluded courtyard garden. The outsized bathtub presides between the indoor and outdoor spaces. As you lie back and soak in the tub, you can gaze through the glass wall into your private garden and view Bali’s tropical sky.","All Village Bungalows are set within a landscaped garden, with a Balinese-style lounging pavilion or balé. The flooring features a variety of handmade ceramic tile types and colors, including red, blue, and terracotta batik tiles, alongside terrazzo flooring."],"showcase":{"wide":{"src":"/reference-rooms/b74dfb6ea4937b20.webp","alt":"Village Bungalow bedroom","category":"Spaces"},"small":{"src":"/reference-rooms/bab9c99758e81319.webp","alt":"Village Bungalow architectural detail","category":"Spaces"},"tall":{"src":"/reference-rooms/2cacc9efe2fe34c7.webp","alt":"Village Bungalow living space","category":"Spaces"},"heading":"Each room at Tandjung Sari has its own unique charm.","body":"The pictures depicted here illustrate the bungalow type mentioned, though you may book this bungalow type and experience a unit with slightly different attributes."},"gallery":[{"id":"photograph-1","image":{"src":"/reference-rooms/6ca1d72b3a14640c.webp","alt":"Village Bungalow bath and courtyard","category":"Spaces"}},{"id":"photograph-2","image":{"src":"/reference-rooms/b0d387542915b5fb.webp","alt":"Village Bungalow bedroom and sitting area","category":"Spaces"}},{"id":"photograph-3","image":{"src":"/reference-rooms/056459f37aa38390.webp","alt":"Village Bungalow garden pavilion","category":"Spaces"}},{"id":"photograph-4","image":{"src":"/reference-rooms/5a0ce4c5054af599.webp","alt":"Village Bungalow interior living space","category":"Spaces"}},{"id":"photograph-5","image":{"src":"/reference-rooms/5d935dc09dd6b150.webp","alt":"Village Bungalow bathroom","category":"Spaces"}},{"id":"photograph-6","image":{"src":"/reference-rooms/86c038b9ea9bcf87.webp","alt":"Village Bungalow terrace","category":"Spaces"}}]}},{"id":"rooms-two-storey-bungalow","slug":"two-storey-bungalow","title":"Two-Storey Bungalow","description":"Tucked away in its own garden with a spacious terrace and polished wooden interiors.","image":{"src":"/reference-rooms/8ef1d619416ca0d3.webp","alt":"Two-Storey Bungalow","category":"Spaces"},"capacity":2,"area":50,"facilities":["Cotton shirt, sarong & sun hat","Bathub","Hairdryer","Minibar","Safety deposit box","Tea/Coffee Maker","Telephone","Wifi"],"inclusions":["Daily ala carte Breakfast in the seaside restaurant","Two bottles of water provided in the room complimentary daily","Cold towel upon arrival","Welcome drink at the beachfront bar"],"signature":{"hero":{"src":"/reference-rooms/8ef1d619416ca0d3.webp","alt":"Two-Storey Bungalow exterior","category":"Spaces"},"heading":"Our four two-storey bungalows are tucked away, each in its own gardens. Each bungalow has a spacious terrace and polished wooden interiors.","body":["Step up to the upper-level living areas, which have windows on three sides, maximizing natural light and garden views.  The ground floor—three units with polished timber floors and the other one with terrazzo tiles—houses a queen-sized canopied bed and a bathroom complete with a handmade terrazzo tub, big enough for two.","Exposed brick, a quirky stone relief, and the antique carved wooden door and windows visually enrich the veranda, which frames a serene private garden."],"showcase":{"wide":{"src":"/reference-rooms/c66840c00ba7f017.webp","alt":"Two-Storey Bungalow bedroom","category":"Spaces"},"small":{"src":"/reference-rooms/1b0f72cae92311be.webp","alt":"Two-Storey Bungalow architectural detail","category":"Spaces"},"tall":{"src":"/reference-rooms/aa3f826d15d55a73.webp","alt":"Two-Storey Bungalow living space","category":"Spaces"},"heading":"Each room at Tandjung Sari has its own unique charm.","body":"The pictures depicted here illustrate the bungalow type mentioned, though you may book this bungalow type and experience a unit with slightly different attributes."},"gallery":[{"id":"photograph-1","image":{"src":"/reference-rooms/ff894b463c129757.webp","alt":"Two-Storey Bungalow bath and courtyard","category":"Spaces"}},{"id":"photograph-2","image":{"src":"/reference-rooms/61bd4d69a6f267a0.webp","alt":"Two-Storey Bungalow bedroom and sitting area","category":"Spaces"}},{"id":"photograph-3","image":{"src":"/reference-rooms/a315917ce861decc.webp","alt":"Two-Storey Bungalow garden pavilion","category":"Spaces"}},{"id":"photograph-4","image":{"src":"/reference-rooms/00a489def911becd.webp","alt":"Two-Storey Bungalow interior living space","category":"Spaces"}},{"id":"photograph-5","image":{"src":"/reference-rooms/a0f5a09a8779ad3c.webp","alt":"Two-Storey Bungalow bathroom","category":"Spaces"}}]}},{"id":"rooms-beachfront-bungalow","slug":"beachfront-bungalow","title":"Beachfront Bungalow","description":"Nestled in a beachside garden, this cozy retreat offers sea views from an upstairs loft.","image":{"src":"/reference-rooms/4f9f73343b2638ac.webp","alt":"Beachfront Bungalow","category":"Spaces"},"capacity":2,"area":55,"facilities":["Cotton shirt, sarong & sun hat","Bathub","Hairdryer","Minibar","Safety deposit box","Tea/Coffee Maker","Telephone","Wifi"],"inclusions":["Daily ala carte Breakfast in the seaside restaurant","Two bottles of water provided in the room complimentary daily","Cold towel upon arrival","Welcome drink at the beachfront bar"],"signature":{"hero":{"src":"/reference-rooms/c53a8138d8de844b.webp","alt":"Beachfront Bungalow exterior","category":"Spaces"},"heading":"Discover the barefoot glamour of our two sanctuaries closest to the beach.","body":["The façade reflects the beauty of traditional Balinese architecture, set within a flourishing beachside courtyard, while the hardwood and bamboo materials deepen your connection to nature. You enter the ground-floor bedroom—one bungalow with a wooden floor and the other with terracotta tile—through an antique Balinese doorway.","The ground floor also features an indoor bathroom and an outdoor shower.  Ascend the spiral staircase to the upper level, where you’ll feel embraced by the treetops. The classic veranda invites you to unwind and enjoy the sights and sounds of the seaside garden."],"showcase":{"wide":{"src":"/reference-rooms/0420b46dffa9e3d8.webp","alt":"Beachfront Bungalow bedroom","category":"Spaces"},"small":{"src":"/reference-rooms/602538ad829201de.webp","alt":"Beachfront Bungalow architectural detail","category":"Spaces"},"tall":{"src":"/reference-rooms/6adff473b5bd13bc.webp","alt":"Beachfront Bungalow living space","category":"Spaces"},"heading":"Each room at Tandjung Sari has its own unique charm.","body":"The pictures depicted here illustrate the bungalow type mentioned, though you may book this bungalow type and experience a unit with slightly different attributes."},"gallery":[{"id":"photograph-1","image":{"src":"/reference-rooms/915686a353285631.webp","alt":"Beachfront Bungalow bath and courtyard","category":"Spaces"}},{"id":"photograph-2","image":{"src":"/reference-rooms/4c4d8ad6c46f0060.webp","alt":"Beachfront Bungalow bedroom and sitting area","category":"Spaces"}},{"id":"photograph-3","image":{"src":"/reference-rooms/9dab833fe1a11072.webp","alt":"Beachfront Bungalow garden pavilion","category":"Spaces"}},{"id":"photograph-4","image":{"src":"/reference-rooms/4af3e7415895ec81.webp","alt":"Beachfront Bungalow interior living space","category":"Spaces"}},{"id":"photograph-5","image":{"src":"/reference-rooms/88fc45a60c9a34d9.webp","alt":"Beachfront Bungalow bathroom","category":"Spaces"}}]}},{"id":"rooms-south-garden-bungalow","slug":"south-garden-bungalow","title":"South Garden Bungalow","description":"The spacious bedroom with canopied queen bed has a large work table and a day bed, ideal for reading.","image":{"src":"/reference-rooms/37ad0a13d67c51f6.webp","alt":"South Garden Bungalow","category":"Spaces"},"capacity":2,"area":128,"facilities":["Cotton shirt, sarong & sun hat","Bathub","Hairdryer","Minibar","Safety deposit box","Tea/Coffee Maker","Telephone","Wifi"],"inclusions":["Daily ala carte Breakfast in the seaside restaurant","Two bottles of water provided in the room complimentary daily","Cold towel upon arrival","Welcome drink at the beachfront bar"],"signature":{"hero":{"src":"/reference-rooms/37ad0a13d67c51f6.webp","alt":"South Garden Bungalow exterior","category":"Spaces"},"heading":"The four inviting units of the South Garden Bungalows are a new generation of bungalows with traditional roofs and sleek interiors—a descriptive intersection between vintage and modern.","body":["Two bungalows boast thatched roofs adorned with blue batik tiles and outdoor bathtubs, while the others feature wood shingle roofs complemented by green celadon batik tiles and indoor bathtubs. Stroll through the gardens and discover the traditionally proportioned veranda, graced with carved wooden pillars, a kamasan painting, and carefully curated antique windows and doors—each element profoundly telling a story of the Tandjung Sari experience.","Inside, spacious bedrooms welcome you with a canopied queen bed, a generous work table and a daybed, ideal for reading. Each bungalow offers a decent bathroom and dressing area, equipped with twin vanity sinks, double wardrobe closets, and an indoor shower with seating. Step beyond the door to uncover an outdoor shower with a refreshing rain showerhead."],"showcase":{"wide":{"src":"/reference-rooms/32e09ec5f44e03cd.webp","alt":"South Garden Bungalow bedroom","category":"Spaces"},"small":{"src":"/reference-rooms/c918e73a55924d26.webp","alt":"South Garden Bungalow architectural detail","category":"Spaces"},"tall":{"src":"/reference-rooms/f855bc9c1e6649eb.webp","alt":"South Garden Bungalow living space","category":"Spaces"},"heading":"Each room at Tandjung Sari has its own unique charm.","body":"The pictures depicted here illustrate the bungalow type mentioned, though you may book this bungalow type and experience a unit with slightly different attributes."},"gallery":[{"id":"photograph-1","image":{"src":"/reference-rooms/63dd944a232d9ee5.webp","alt":"South Garden Bungalow bath and courtyard","category":"Spaces"}},{"id":"photograph-2","image":{"src":"/reference-rooms/ac796aeefb254c6f.webp","alt":"South Garden Bungalow bedroom and sitting area","category":"Spaces"}},{"id":"photograph-3","image":{"src":"/reference-rooms/bb008ddbb7268e74.webp","alt":"South Garden Bungalow garden pavilion","category":"Spaces"}},{"id":"photograph-4","image":{"src":"/reference-rooms/9b51273f484e109a.webp","alt":"South Garden Bungalow interior living space","category":"Spaces"}},{"id":"photograph-5","image":{"src":"/reference-rooms/5c374843b8fd1a6c.webp","alt":"South Garden Bungalow bathroom","category":"Spaces"}},{"id":"photograph-6","image":{"src":"/reference-rooms/f24d883d475f62e9.webp","alt":"South Garden Bungalow terrace","category":"Spaces"}}]}},{"id":"rooms-garden-seaview-bungalow","slug":"garden-seaview-bungalow","title":"Garden Seaview Bungalow","description":"Charming bungalow in a secluded garden, with a spacious veranda and views to the sea.","image":{"src":"/reference-rooms/50294ef5a663cd15.webp","alt":"Garden Seaview Bungalow","category":"Spaces"},"capacity":2,"area":70,"facilities":["Cotton shirt, sarong & sun hat","Bathub","Hairdryer","Minibar","Safety deposit box","Tea/Coffee maker","Telephone","Wifi"],"inclusions":["Daily ala carte Breakfast in the seaside restaurant","Two bottles of water provided in the room complimentary daily","Cold towel upon arrival","Welcome drink at the beachfront bar"],"signature":{"hero":{"src":"/reference-rooms/50294ef5a663cd15.webp","alt":"Garden Seaview Bungalow exterior","category":"Spaces"},"heading":"Explore and encounter the soul of the Garden Seaview Bungalow #24 — a unique bungalow with its own secluded leafy garden, spacious airy veranda, and front-on-ocean vistas.","body":["This bungalow captivates with its antique entry door. As you enter, you will be delighted with the warmth of the terracotta-colored batik tiles. Further, you will notice the ivory oval indoor bathtub complemented by an indoor shower and a classic modern dressing table.","The backyard features a tropical outdoor shower, for bathing in the midst of nature. Each carefully curated piece of furniture, artwork, and ornament infuses the space with a quiet spell."],"showcase":{"wide":{"src":"/reference-rooms/75604cc478c7e300.webp","alt":"Garden Seaview Bungalow bedroom","category":"Spaces"},"small":{"src":"/reference-rooms/74b7782a47890edd.webp","alt":"Garden Seaview Bungalow architectural detail","category":"Spaces"},"tall":{"src":"/reference-rooms/8d8a081dcc581a90.webp","alt":"Garden Seaview Bungalow living space","category":"Spaces"},"heading":"Each room at Tandjung Sari has its own unique charm.","body":"The pictures depicted here illustrate the bungalow type mentioned, though you may book this bungalow type and experience a unit with slightly different attributes."},"gallery":[{"id":"photograph-1","image":{"src":"/reference-rooms/8059441e5e122b08.webp","alt":"Garden Seaview Bungalow bath and courtyard","category":"Spaces"}},{"id":"photograph-2","image":{"src":"/reference-rooms/19629064fd905164.webp","alt":"Garden Seaview Bungalow bedroom and sitting area","category":"Spaces"}},{"id":"photograph-3","image":{"src":"/reference-rooms/8a365dacce5af6af.webp","alt":"Garden Seaview Bungalow garden pavilion","category":"Spaces"}},{"id":"photograph-4","image":{"src":"/reference-rooms/2679a71afa843ae2.webp","alt":"Garden Seaview Bungalow interior living space","category":"Spaces"}},{"id":"photograph-5","image":{"src":"/reference-rooms/c09d6c04ed64fffc.webp","alt":"Garden Seaview Bungalow bathroom","category":"Spaces"}},{"id":"photograph-6","image":{"src":"/reference-rooms/4f6a3ae37818944d.webp","alt":"Garden Seaview Bungalow terrace","category":"Spaces"}}]}},{"id":"rooms-family-bungalow","slug":"family-bungalow","title":"Family Bungalow","description":"The Family Bungalows are designed to provide a cozy getaway for families in Sanur, offering comfort and tranquility with interconnected sleeping areas, terraces, and gardens. Each bungalow features two bedrooms: one with a queen-sized bed and another with two twin beds.","image":{"src":"/reference-rooms/23cc47b4582b9331.webp","alt":"Family Bungalow","category":"Spaces"},"capacity":4,"area":135,"facilities":["Cotton shirt, sarong & sun hat","Bathub","Hairdryer","Minibar","Safety deposit box","Tea/Coffee Maker","Telephone","Wifi"],"inclusions":["Daily ala carte Breakfast in the seaside restaurant","Two bottles of water provided in the room complimentary daily","Cold towel upon arrival","Welcome drink at the beachfront bar"],"signature":{"hero":{"src":"/reference-rooms/4ad25185c5b1d69a.webp","alt":"Family Bungalow exterior","category":"Spaces"},"heading":"The Family Bungalows are designed to provide a cozy getaway for families in Sanur, offering comfort and tranquility with interconnected sleeping areas, terraces, and gardens.","body":["Each bungalow features two bedrooms: one with a queen-sized bed and another with two twin beds. These rooms embody the unique style of Tandjung Sari while showcasing their own individual character.","As you approach the bungalows, you will notice a Kamasan painting displayed above the door. Inside, the bungalows are adorned with a light green color scheme and batik floor tiles. Each bungalow also includes a family bathtub overlooking the backyard garden, along with outdoor showers."],"showcase":{"wide":{"src":"/reference-rooms/5019670d82b75845.webp","alt":"Family Bungalow bedroom","category":"Spaces"},"small":{"src":"/reference-rooms/6bcbcf2239194086.webp","alt":"Family Bungalow architectural detail","category":"Spaces"},"tall":{"src":"/reference-rooms/bf121188e08e15d3.webp","alt":"Family Bungalow living space","category":"Spaces"},"heading":"Each room at Tandjung Sari has its own unique charm.","body":"The pictures depicted here illustrate the bungalow type mentioned, though you may book this bungalow type and experience a unit with slightly different attributes."},"gallery":[{"id":"photograph-1","image":{"src":"/reference-rooms/7ebd7680a137cf0a.webp","alt":"Family Bungalow bath and courtyard","category":"Spaces"}},{"id":"photograph-2","image":{"src":"/reference-rooms/2ebac394a22d2490.webp","alt":"Family Bungalow bedroom and sitting area","category":"Spaces"}},{"id":"photograph-3","image":{"src":"/reference-rooms/5b8285feef0af434.webp","alt":"Family Bungalow garden pavilion","category":"Spaces"}},{"id":"photograph-4","image":{"src":"/reference-rooms/f5adda664a784d5e.webp","alt":"Family Bungalow interior living space","category":"Spaces"}}]}}],"signatureRooms":{"title":"Our Rooms","hero":{"src":"/reference-story/hero-image-bungalow-resizedjpg.jpeg","alt":"Aerial photograph of Tandjung Sari bungalows","category":"Spaces"},"heading":"Tandjung Sari is a handmade resort. The resorts \"rooms\" are stand-alone cottages—always called bungalows—set in walled gardens.","smallImage":{"src":"/reference-rooms/df530c83448f8ad2.webp","alt":"Handmade Village Bungalow interior","category":"Spaces"},"smallCopy":"Local craftsmen constructed them organically, showcasing the resort's distinctive handmade character in its architecture, interiors, and furnishings.","largeImage":{"src":"/reference-rooms/05367bbc53f7f29a.webp","alt":"Traditional carved gateway at Tandjung Sari","category":"Spaces"},"largeCopy":"These bungalows are thoughtfully placed throughout the property and were beautifully designed based on a sketch by the founder, Wija Wawo-Runtu.","ornament":{"src":"/reference-rooms/listing-ornament.svg","alt":"Coral ornament","category":"Spaces"}},"modules":{"dining":true,"experiences":true,"packages":true,"terms":true},"dining":{"title":"Culinary","description":"The Restaurant at Tandjung Sari offers you more than a seaside dining experience. You may choose to dine in the airy wantilan pavilion amongst Indonesian antiques or on the wooden deck under the shady camplung trees near the bar area, right on Sanur Beach. Our homemade cuisine reflects our passion for authentic local and international food, accompanied by specially crafted drinks. Open every day, from 6.30am to 11pm.","image":{"src":"/reference-dining/a0cdcf1d52648a3898dc.webp","alt":"Dining illustrated Balinese village","category":"Spaces"},"bookingUrl":"https://example.com/dining","signature":{"introTitle":"The Restaurant at Tandjung Sari","categories":[{"id":"breakfast","enabled":true,"title":"Breakfast","description":"Sanur, the \"Morning of the World,\" unveils a breathtaking moment when the sun rises, casting a golden glow on the sand and igniting the sky with color—a true masterpiece of nature. There are countless ways to start the day, but is there a better way than to savor breakfast while witnessing a natural wonder?","image":{"src":"/reference-dining/08038031e1c9a5f9d48f.webp","alt":"Breakfast","category":"Spaces"},"menuPages":[{"id":"breakfast-page-1","image":{"src":"/reference-dining/2a40a45176a72df0f947.webp","alt":"Breakfast menu page 1","category":"Spaces"},"width":2044,"height":2892},{"id":"breakfast-page-2","image":{"src":"/reference-dining/326fb61058fa95492bbd.webp","alt":"Breakfast menu page 2","category":"Spaces"},"width":2044,"height":2892},{"id":"breakfast-page-3","image":{"src":"/reference-dining/5a5b0cb2e49bf92bfa58.webp","alt":"Breakfast menu page 3","category":"Spaces"},"width":2044,"height":2892}],"mobileMenuPages":[{"id":"breakfast-mobile-page-1","image":{"src":"/reference-dining/2a40a45176a72df0f947.webp","alt":"Breakfast mobile menu page 1","category":"Spaces"},"width":2044,"height":2892},{"id":"breakfast-mobile-page-2","image":{"src":"/reference-dining/6b7994f03543d42c649a.webp","alt":"Breakfast mobile menu page 2","category":"Spaces"},"width":955,"height":1550},{"id":"breakfast-mobile-page-3","image":{"src":"/reference-dining/12c2f1dad84004dcf165.webp","alt":"Breakfast mobile menu page 3","category":"Spaces"},"width":1911,"height":3100},{"id":"breakfast-mobile-page-4","image":{"src":"/reference-dining/ac51c616c72b18737e62.webp","alt":"Breakfast mobile menu page 4","category":"Spaces"},"width":955,"height":1550},{"id":"breakfast-mobile-page-5","image":{"src":"/reference-dining/466218676adaad5b0931.webp","alt":"Breakfast mobile menu page 5","category":"Spaces"},"width":955,"height":1550}],"downloadUrl":""},{"id":"all-day-dining","enabled":true,"title":"All Day Dining","description":"Ever since our founder established Tandjung Sari as a family home, food has held equal importance to accommodation. Today, we continue to uphold the principles of home cooking. Created from fresh, locally grown produce and ingredients, we offer signature authentic local and international cuisine.","image":{"src":"/reference-dining/bb606c5e0861898c03c3.webp","alt":"All Day Dining","category":"Spaces"},"menuPages":[{"id":"all-day-dining-page-1","image":{"src":"/reference-dining/19fb1a774784a436926c.webp","alt":"All Day Dining menu page 1","category":"Spaces"},"width":1022,"height":1446},{"id":"all-day-dining-page-2","image":{"src":"/reference-dining/d1c764ed999f94b20b48.webp","alt":"All Day Dining menu page 2","category":"Spaces"},"width":1022,"height":1446},{"id":"all-day-dining-page-3","image":{"src":"/reference-dining/d5ecbf5b29ee1be7f2d1.webp","alt":"All Day Dining menu page 3","category":"Spaces"},"width":1022,"height":1446},{"id":"all-day-dining-page-4","image":{"src":"/reference-dining/396db0c7f2d9b6854ed3.webp","alt":"All Day Dining menu page 4","category":"Spaces"},"width":1022,"height":1446}],"mobileMenuPages":[{"id":"all-day-dining-mobile-page-1","image":{"src":"/reference-dining/4a2e0e638209b074b832.webp","alt":"All Day Dining mobile menu page 1","category":"Spaces"},"width":955,"height":1550},{"id":"all-day-dining-mobile-page-2","image":{"src":"/reference-dining/7ae21801d46892e134ca.webp","alt":"All Day Dining mobile menu page 2","category":"Spaces"},"width":955,"height":1550},{"id":"all-day-dining-mobile-page-3","image":{"src":"/reference-dining/1d80ffc9713f056df173.webp","alt":"All Day Dining mobile menu page 3","category":"Spaces"},"width":955,"height":1550},{"id":"all-day-dining-mobile-page-4","image":{"src":"/reference-dining/0a520d9884f1a4026d4a.webp","alt":"All Day Dining mobile menu page 4","category":"Spaces"},"width":955,"height":1550},{"id":"all-day-dining-mobile-page-5","image":{"src":"/reference-dining/98fe51403f3f25d94205.webp","alt":"All Day Dining mobile menu page 5","category":"Spaces"},"width":955,"height":1550},{"id":"all-day-dining-mobile-page-6","image":{"src":"/reference-dining/0fcf9ed4a8a21170fd69.webp","alt":"All Day Dining mobile menu page 6","category":"Spaces"},"width":955,"height":1550}],"downloadUrl":""},{"id":"drinks","enabled":true,"title":"Drinks & Wines","description":"Tandjung Sari's beachfront bar is the ultimate place to gather at all hours of the day. The bar menu offers a hand-picked selection of refreshments with fresh tropical flavors—whether soft, sweet, or a bit stronger. Contact us to explore our selection of wines and take advantage of special offers designed for wine enthusiasts.","image":{"src":"/reference-dining/2486277bb07cc788020e.webp","alt":"Drinks & Wines","category":"Spaces"},"menuPages":[{"id":"drinks-page-1","image":{"src":"/reference-dining/f7c87a41940942f0d53e.webp","alt":"Drinks menu page 1","categor